        subsetSum(nums, sy, i + 1, n, rk);
        rk.pop_back();
        for (int j = i; j < nums.size(); j++) {
            if (nums[j] != nums[j + 1]) {
                subsetSum(nums, sy, j + 1, n, rk);
                break;
            }
            subsetSum(nums,sy,n,n,rk);
        }
    }
