public class Solution
{
    public List<List<int>> SubsetsWithDup(List<int> nums)
    {
        // Raj Thomas 11th May 2026 11:09PM IST
        List<List<int>> result = new List<List<int>>();
        List<int> item = new List<int>();
        nums.Sort();
        Backtrack(nums, 0, result, item);
        return result;
    }

    private void Backtrack(List<int> nums, int idx,
                        List<List<int>> result,
                        List<int> item) {

        result.Add(new List<int>(item));

        for(int i = idx; i < nums.Count; i++) {

            if(idx < i && nums[i - 1] == nums[i]) continue;

            item.Add(nums[i]);
            Backtrack(nums, i + 1, result, item);
            item.RemoveAt(item.Count - 1);
        }
    }
}
```

